import os
from typing import Any, Dict, List, Optional

import requests


class StructuredDocumentExtractionError(Exception):
    pass


def validate_structured_document(
    document_text: str,
    required_fields: List[str],
    min_confidence: float = 0.8,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Validates required structured fields and confidence scores using Google Cloud Document AI.

    Expects the hosted API to return structured document entities. Validates that each
    required field exists and has confidence >= min_confidence.

    Returns a normalized result dictionary:
    {
        "valid": bool,
        "missing_fields": [...],
        "low_confidence_fields": [{"field": ..., "confidence": ...}, ...],
        "fields": {field_name: {"value": ..., "confidence": ...}, ...},
        "raw_response": {...}
    }
    """
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    location = os.getenv("GOOGLE_CLOUD_LOCATION", "us")
    processor_id = os.getenv("GOOGLE_DOCUMENT_AI_PROCESSOR_ID")

    if not project_id or not processor_id:
        raise StructuredDocumentExtractionError(
            "Missing GOOGLE_CLOUD_PROJECT or GOOGLE_DOCUMENT_AI_PROCESSOR_ID environment variable."
        )

    api_key = api_key or os.getenv("GOOGLE_API_KEY")
    if not api_key:
        raise StructuredDocumentExtractionError("Missing GOOGLE_API_KEY or api_key.")

    url = (
        f"https://documentai.googleapis.com/v1/projects/{project_id}/locations/{location}"
        f"/processors/{processor_id}:process"
    )

    payload = {
        "rawDocument": {
            "content": document_text.encode("utf-8").hex(),
            "mimeType": "text/plain",
        }
    }

    # Document AI expects base64-encoded content; keep integration concrete and hosted.
    import base64

    payload["rawDocument"]["content"] = base64.b64encode(document_text.encode("utf-8")).decode("ascii")

    headers = {
        "Content-Type": "application/json",
        "x-goog-api-key": api_key,
    }

    response = requests.post(url, json=payload, headers=headers, timeout=60)
    if not response.ok:
        raise StructuredDocumentExtractionError(
            f"Document AI request failed: {response.status_code} {response.text}"
        )

    data = response.json()
    document = data.get("document", {})
    entities = document.get("entities", [])

    extracted_fields: Dict[str, Dict[str, Any]] = {}
    for entity in entities:
        name = entity.get("type") or entity.get("mentionText") or entity.get("normalizedValue", {}).get("text")
        if not name:
            continue

        value = entity.get("mentionText")
        if value is None:
            normalized = entity.get("normalizedValue", {})
            value = normalized.get("text") or normalized.get("dateValue") or normalized.get("moneyValue") or normalized.get("floatValue")

        confidence = entity.get("confidence")
        extracted_fields[name] = {"value": value, "confidence": confidence}

    missing_fields = []
    low_confidence_fields = []

    for field in required_fields:
        if field not in extracted_fields:
            missing_fields.append(field)
            continue

        confidence = extracted_fields[field].get("confidence")
        if confidence is None or float(confidence) < float(min_confidence):
            low_confidence_fields.append(
                {"field": field, "confidence": confidence}
            )

    valid = not missing_fields and not low_confidence_fields

    return {
        "valid": valid,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "fields": extracted_fields,
        "raw_response": data,
    }
